arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_458d9bc9b5754495ac2529ad2cf106ef.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1 class="mb-4">Job Application</h1>

@if (_submitted)
{
    <div class="alert alert-success text-center py-5">
        <h2>✅ Application Submitted!</h2>
        <p class="lead mt-3">Your application has been received.</p>
        <p>Application ID: <strong>@_applicationId</strong></p>
        <button class="btn btn-primary mt-3" @onclick="ResetForm">Submit Another Application</button>
    </div>
}
else
{
    <!-- Step Indicator -->
    <nav class="mb-4">
        <ol class="d-flex list-unstyled justify-content-between step-indicator">
            @for (int i = 0; i < _stepLabels.Length; i++)
            {
                var stepIndex = i;
                var isCompleted = stepIndex < _currentStep;
                var isCurrent = stepIndex == _currentStep;
                var isFuture = stepIndex > _currentStep;

                <li class="text-center flex-fill position-relative step-item
                           @(isCurrent ? "step-current" : "") @(isCompleted ? "step-completed" : "") @(isFuture ? "step-future" : "")">
                    @if (isCompleted)
                    {
                        <button class="btn btn-link text-decoration-none p-0" @onclick="() => GoToStep(stepIndex)">
                            <span class="step-circle bg-success text-white">✓</span>
                            <div class="small mt-1 text-success fw-semibold">@_stepLabels[stepIndex]</div>
                        </button>
                    }
                    else
                    {
                        <span class="step-circle @(isCurrent ? "bg-primary text-white" : "bg-secondary text-white opacity-50")">@(stepIndex + 1)</span>
                        <div class="small mt-1 @(isCurrent ? "fw-semibold text-primary" : "text-muted")">@_stepLabels[stepIndex]</div>
                    }
                </li>
            }
        </ol>
    </nav>

    <!-- Validation Errors -->
    @if (_errors.Count > 0)
    {
        <div class="alert alert-danger">
            <ul class="mb-0">
                @foreach (var error in _errors)
                {
                    <li>@error</li>
                }
            </ul>
        </div>
    }

    <!-- Step Content -->
    @switch (_currentStep)
    {
        case 0:
            <StepPersonalInfo @bind-FullName="_fullName"
                              @bind-Email="_email"
                              @bind-Phone="_phone"
                              @bind-Address="_address" />
            break;
        case 1:
            <StepWorkHistory Entries="_workEntries"
                             OnAddEntry="AddWorkEntry"
                             OnRemoveEntry="RemoveWorkEntry" />
            break;
        case 2:
            <StepReferences References="_references"
                            OnAddReference="AddReference"
                            OnRemoveReference="RemoveReference" />
            break;
        case 3:
            <StepCoverLetter @bind-CoverLetter="_coverLetter" MaxLength="2000" />
            break;
        case 4:
            <StepReview FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                        WorkEntries="_workEntries" References="_references" CoverLetter="@_coverLetter"
                        OnEditSection="GoToStep" />
            break;
    }

    <!-- Navigation Buttons -->
    <div class="d-flex justify-content-between mt-4">
        <div>
            @if (_currentStep > 0)
            {
                <button class="btn btn-outline-secondary" @onclick="PreviousStep" disabled="@_isProcessing">
                    ← Back
                </button>
            }
        </div>
        <div>
            @if (_currentStep < _stepLabels.Length - 1)
            {
                <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">
                    @if (_isProcessing)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Next →
                </button>
            }
            else
            {
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isProcessing">
                    @if (_isProcessing)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        <span>Submitting…</span>
                    }
                    else
                    {
                        <span>Submit Application</span>
                    }
                </button>
            }
        </div>
    </div>
}

@code {
