@code {
    private static readonly string[] _stepLabels = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int _currentStep;
    private bool _isProcessing;
    private bool _submitted;
    private int _applicationId;
    private List<string> _errors = [];

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2
    private List<WorkEntryModel> _workEntries = [new()];

    // Step 3
    private List<ReferenceModel> _references = [new(), new()];

    // Step 4
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        _errors.Clear();
        _currentStep = step;
    }

    private void PreviousStep()
    {
        _errors.Clear();
        _currentStep--;
    }

    private async Task NextStep()
    {
        _errors.Clear();

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 0)
        {
            _isProcessing = true;
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            _isProcessing = false;

            if (!emailValid)
            {
                _errors.Add("Please enter a valid email address.");
                return;
            }
        }

        _currentStep++;
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(_fullName)) _errors.Add("Full name is required.");
                if (string.IsNullOrWhiteSpace(_email)) _errors.Add("Email is required.");
                if (string.IsNullOrWhiteSpace(_phone)) _errors.Add("Phone is required.");
                if (string.IsNullOrWhiteSpace(_address)) _errors.Add("Address is required.");
                break;
            case 1:
                for (int i = 0; i < _workEntries.Count; i++)
                {
                    var e = _workEntries[i];
                    var pos = _workEntries.Count > 1 ? $" (Position {i + 1})" : "";
                    if (string.IsNullOrWhiteSpace(e.Company)) _errors.Add($"Company name is required{pos}.");
                    if (string.IsNullOrWhiteSpace(e.Title)) _errors.Add($"Job title is required{pos}.");
                    if (e.StartDate == default) _errors.Add($"Start date is required{pos}.");
                    if (string.IsNullOrWhiteSpace(e.Description)) _errors.Add($"Description is required{pos}.");
                }
                break;
            case 2:
                if (_references.Count < 2) _errors.Add("At least 2 references are required.");
                for (int i = 0; i < _references.Count; i++)
                {
                    var r = _references[i];
                    var refLabel = $" (Reference {i + 1})";
