+                    if (string.IsNullOrWhiteSpace(r.Name)) _errors.Add($"Name is required{refLabel}.");
+                    if (string.IsNullOrWhiteSpace(r.Relationship)) _errors.Add($"Relationship is required{refLabel}.");
+                    if (string.IsNullOrWhiteSpace(r.Email)) _errors.Add($"Email is required{refLabel}.");
+                    if (string.IsNullOrWhiteSpace(r.Phone)) _errors.Add($"Phone is required{refLabel}.");
+                }
+                break;
+            case 3:
+                if (string.IsNullOrWhiteSpace(_coverLetter)) _errors.Add("Cover letter is required.");
+                break;
+        }
+
+        return _errors.Count == 0;
+    }
+
+    private async Task SubmitApplication()
+    {
+        _errors.Clear();
+        _isProcessing = true;
+
+        var application = new JobApplication(
+            new PersonalInfo(_fullName, _email, _phone, _address),
+            new WorkHistory(_workEntries.Select(e => new WorkEntry(
+                e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
+            _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
+            _coverLetter
+        );
+
+        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
+        _isProcessing = false;
+        _submitted = true;
+    }
+
+    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());
+    private void RemoveWorkEntry(WorkEntryModel entry) => _workEntries.Remove(entry);
+    private void AddReference()
+    {
+        if (_references.Count < 3) _references.Add(new ReferenceModel());
+    }
+    private void RemoveReference(ReferenceModel reference) => _references.Remove(reference);
+
+    private void ResetForm()
+    {
+        _currentStep = 0;
+        _submitted = false;
+        _applicationId = 0;
+        _errors.Clear();
+        _fullName = _email = _phone = _address = _coverLetter = "";
+        _workEntries = [new()];
+        _references = [new(), new()];
+    }
+
+    public class WorkEntryModel
+    {
+        public string Company { get; set; } = "";
+        public string Title { get; set; } = "";
+        public DateTime StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = "";
+    }
+
+    public class ReferenceModel
+    {
+        public string Name { get; set; } = "";
+        public string Relationship { get; set; } = "";
+        public string Email { get; set; } = "";
+        public string Phone { get; set; } = "";
+    }
+}
