@using static Apply

<div class="card">
    <div class="card-body">
        <h3 class="card-title mb-3">References</h3>
        <p class="text-muted">Please provide 2–3 professional references.</p>

        @for (int i = 0; i < References.Count; i++)
        {
            var reference = References[i];
            var index = i;

            <div class="border rounded p-3 mb-3 position-relative">
                <h5>Reference @(index + 1)</h5>

                @if (References.Count > 2)
                {
                    <button class="btn btn-sm btn-outline-danger position-absolute top-0 end-0 m-2"
                            @onclick="() => OnRemoveReference.InvokeAsync(reference)">
                        ✕ Remove
                    </button>
                }

                <div class="row">
                    <div class="col-md-6 mb-3">
                        <label class="form-label">Name <span class="text-danger">*</span></label>
                        <input type="text" class="form-control" @bind="reference.Name" placeholder="Jane Smith" />
                    </div>
                    <div class="col-md-6 mb-3">
                        <label class="form-label">Relationship <span class="text-danger">*</span></label>
                        <input type="text" class="form-control" @bind="reference.Relationship" placeholder="Former Manager" />
                    </div>
                </div>
                <div class="row">
                    <div class="col-md-6 mb-3">
                        <label class="form-label">Email <span class="text-danger">*</span></label>
                        <input type="email" class="form-control" @bind="reference.Email" placeholder="jane@example.com" />
                    </div>
                    <div class="col-md-6 mb-3">
                        <label class="form-label">Phone <span class="text-danger">*</span></label>
                        <input type="tel" class="form-control" @bind="reference.Phone" placeholder="(555) 987-6543" />
                    </div>
                </div>
            </div>
        }

        @if (References.Count < 3)
        {
            <button class="btn btn-outline-primary" @onclick="() => OnAddReference.InvokeAsync()">
                + Add Reference
            </button>
        }
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = [];
    [Parameter] public EventCallback OnAddReference { get; set; }
    [Parameter] public EventCallback<ReferenceModel> OnRemoveReference { get; set; }
}

